import { knowledgeBases } from '../data/mockData.js';

export class Sidebar {
  constructor(container) {
    this.container = container;
    this.navItems = [
      { id: 'list', label: '知识库列表', icon: '📚' },
      { id: 'detail', label: '知识库详情', icon: '📄' },
      { id: 'userChat', label: '用户聊天', icon: '💬' },
    ];
    this.systemItems = [
      { id: 'settings', label: '设置', icon: '⚙️' },
      { id: 'theme', label: '主题', icon: '🎨' },
    ];
    this.activeItem = 'list';
    this.activeKB = null;
    this.searchQuery = '';
    this.expandedGroups = {
      recent: true,
      favorites: true,
      documents: true,
      qa: true,
      web: true,
    };
    this.render();
  }

  getFavorites() {
    const favIds = JSON.parse(localStorage.getItem('kb_favorites') || '[]');
    return knowledgeBases.filter((kb) => favIds.includes(kb.id));
  }

  getRecent() {
    const recent = JSON.parse(localStorage.getItem('kb_recent') || '[]');
    return recent
      .map((item) => knowledgeBases.find((kb) => kb.id === item.id))
      .filter(Boolean)
      .slice(0, 5);
  }

  addToRecent(kbId) {
    const recent = JSON.parse(localStorage.getItem('kb_recent') || '[]');
    const existing = recent.findIndex((item) => item.id === kbId);
    if (existing !== -1) {
      recent.splice(existing, 1);
    }
    recent.unshift({ id: kbId, time: Date.now() });
    localStorage.setItem('kb_recent', JSON.stringify(recent.slice(0, 10)));
  }

  toggleFavorite(kbId) {
    const favIds = JSON.parse(localStorage.getItem('kb_favorites') || '[]');
    const index = favIds.indexOf(kbId);
    if (index === -1) {
      favIds.push(kbId);
    } else {
      favIds.splice(index, 1);
    }
    localStorage.setItem('kb_favorites', JSON.stringify(favIds));
    this.render();
  }

  getKBsByType(type) {
    return knowledgeBases.filter((kb) => kb.type === type);
  }

  filterKBs(kbs) {
    if (!this.searchQuery) return kbs;
    const query = this.searchQuery.toLowerCase();
    return kbs.filter(
      (kb) =>
        kb.name.toLowerCase().includes(query) ||
        kb.description.toLowerCase().includes(query)
    );
  }

  render() {
    const favorites = this.getFavorites();
    const recent = this.getRecent();
    const documents = this.getKBsByType('文档');
    const qa = this.getKBsByType('问答');
    const web = this.getKBsByType('网页');

    const filteredRecent = this.filterKBs(recent);
    const filteredFavorites = this.filterKBs(favorites);
    const filteredDocuments = this.filterKBs(documents);
    const filteredQA = this.filterKBs(qa);
    const filteredWeb = this.filterKBs(web);

    this.container.innerHTML = `
      <aside class="sidebar">
        <div class="logo">
          <div class="logo-icon">S</div>
          SSO Hub
        </div>

        <div class="kb-section">
          <div class="kb-section-title">我的知识库</div>
          
          <div class="kb-search">
            <input 
              type="text" 
              id="kb-sidebar-search" 
              placeholder="搜索知识库 (Ctrl+K)"
              value="${this.searchQuery}"
            >
            <span class="search-icon">🔍</span>
          </div>

          ${this.renderRecentSection(filteredRecent)}
          ${this.renderFavoritesSection(filteredFavorites)}
          ${this.renderGroupSection('documents', '📄 文档', filteredDocuments)}
          ${this.renderGroupSection('qa', '💬 问答', filteredQA)}
          ${this.renderGroupSection('web', '🌐 网页', filteredWeb)}
        </div>

        <nav class="nav">
          <div class="nav-section">系统</div>
          ${this.systemItems
            .map(
              (item) => `
            <div
              class="nav-item ${this.activeItem === item.id ? 'active' : ''}"
              data-id="${item.id}"
            >
              ${item.icon} ${item.label}
            </div>
          `
            )
            .join('')}
        </nav>
      </aside>
    `;

    this.bindEvents();
  }

  renderRecentSection(kbs) {
    if (kbs.length === 0) return '';
    return `
      <div class="kb-group">
        <div class="kb-group-header" data-group="recent">
          <span class="kb-group-icon">🕐</span>
          <span class="kb-group-name">最近使用</span>
          <span class="kb-group-count">${kbs.length}</span>
          <span class="kb-group-arrow">▼</span>
        </div>
        <div class="kb-group-content ${this.expandedGroups.recent ? '' : 'collapsed'}">
          ${kbs.map((kb) => this.renderKBItem(kb)).join('')}
        </div>
      </div>
    `;
  }

  renderFavoritesSection(kbs) {
    if (kbs.length === 0) return '';
    return `
      <div class="kb-group">
        <div class="kb-group-header" data-group="favorites">
          <span class="kb-group-icon">⭐</span>
          <span class="kb-group-name">我的收藏</span>
          <span class="kb-group-count">${kbs.length}</span>
          <span class="kb-group-arrow">▼</span>
        </div>
        <div class="kb-group-content ${this.expandedGroups.favorites ? '' : 'collapsed'}">
          ${kbs.map((kb) => this.renderKBItem(kb)).join('')}
        </div>
      </div>
    `;
  }

  renderGroupSection(groupId, title, kbs) {
    if (kbs.length === 0) return '';
    const hasMore = kbs.length > 5;
    const displayKBs = hasMore ? kbs.slice(0, 5) : kbs;

    return `
      <div class="kb-group">
        <div class="kb-group-header" data-group="${groupId}">
          <span class="kb-group-name">${title}</span>
          <span class="kb-group-count">${kbs.length}</span>
          <span class="kb-group-arrow">▼</span>
        </div>
        <div class="kb-group-content ${this.expandedGroups[groupId] ? '' : 'collapsed'}">
          ${displayKBs.map((kb) => this.renderKBItem(kb)).join('')}
          ${hasMore ? '<div class="kb-view-all" data-group="' + groupId + '">📋 查看全部 (' + kbs.length + ')</div>' : ''}
        </div>
      </div>
    `;
  }

  renderKBItem(kb) {
    const favIds = JSON.parse(localStorage.getItem('kb_favorites') || '[]');
    const isFavorite = favIds.includes(kb.id);
    const isActive = this.activeKB === kb.id;

    return `
      <div 
        class="kb-item ${isActive ? 'active' : ''}" 
        data-id="${kb.id}"
      >
        <span class="kb-item-icon">${this.getTypeIcon(kb.type)}</span>
        <div class="kb-item-info">
          <div class="kb-item-name">${kb.name}</div>
          <div class="kb-item-count">${kb.documentCount} 文档</div>
        </div>
        <button 
          class="kb-fav-btn ${isFavorite ? 'favorited' : ''}" 
          data-id="${kb.id}"
          title="${isFavorite ? '取消收藏' : '收藏'}"
        >
          ${isFavorite ? '⭐' : '☆'}
        </button>
      </div>
    `;
  }

  getTypeIcon(type) {
    const icons = {
      '文档': '📄',
      '问答': '💬',
      '网页': '🌐',
    };
    return icons[type] || '📁';
  }

  bindEvents() {
    const searchInput = document.getElementById('kb-sidebar-search');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        this.searchQuery = e.target.value;
        this.render();
      });
    }

    document.addEventListener('keydown', (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        const searchInput = document.getElementById('kb-sidebar-search');
        if (searchInput) {
          searchInput.focus();
        }
      }
    });

    this.container.addEventListener('click', (e) => {
      const groupHeader = e.target.closest('.kb-group-header');
      if (groupHeader) {
        const groupId = groupHeader.dataset.group;
        this.expandedGroups[groupId] = !this.expandedGroups[groupId];
        this.render();
        return;
      }

      const kbItem = e.target.closest('.kb-item');
      if (kbItem) {
        const kbId = kbItem.dataset.id;
        const kb = knowledgeBases.find((k) => k.id === kbId);
        if (kb) {
          this.addToRecent(kbId);
          this.activeKB = kbId;
          this.activeItem = 'detail';
          this.render();
          this.onKBSelect?.(kb);
        }
        return;
      }

      const favBtn = e.target.closest('.kb-fav-btn');
      if (favBtn) {
        e.stopPropagation();
        this.toggleFavorite(favBtn.dataset.id);
        return;
      }

      const viewAll = e.target.closest('.kb-view-all');
      if (viewAll) {
        this.activeItem = 'list';
        this.render();
        this.onNavChange?.('list');
        return;
      }

      const navItem = e.target.closest('.nav-item');
      if (navItem) {
        const id = navItem.dataset.id;
        this.activeItem = id;
        this.render();
        this.onNavChange?.(id);
      }
    });
  }

  setOnNavChange(callback) {
    this.onNavChange = callback;
  }

  setOnKBSelect(callback) {
    this.onKBSelect = callback;
  }

  setActive(itemId) {
    this.activeItem = itemId;
    this.render();
  }

  setActiveKB(kbId) {
    this.activeKB = kbId;
    this.render();
  }
}
